static std::uint64_t sink=0;
int main(int argc,char**argv){if(argc!=4)return 1;const auto n=static_cast<std::size_t>(std::strtoull(argv[1],nullptr,10));constexpr int op=OP;const auto base=std::strtoull(argv[3],nullptr,10);std::string s(n,'a');std::mt19937 rng(731521);for(auto&c:s)c=static_cast<char>(rng());const std::size_t reps=std::max(std::size_t{4},std::min(std::size_t{20000},std::size_t{4000000}/(n+1)));RollingHash h(s,base);for(int warm=0;warm<2;++warm)h.assign(s);auto start=Clock::now();for(std::size_t rep=0;rep<reps;++rep){if(op==0){RollingHash t(s,base);sink+=t.whole()+t.get(n/3,n/2)+t.concat(1,1,n/4);}else if(op==1){h.assign(s);sink+=h.whole()+h.get(n/3,n/2);}else{h.clear();h.assign(s);sink+=h.whole()+h.get(n/3,n/2);}std::atomic_signal_fence(std::memory_order_seq_cst);}auto stop=Clock::now();std::printf("%.3f %llu\n",double(std::chrono::duration_cast<std::chrono::nanoseconds>(stop-start).count())/reps,static_cast<unsigned long long>(sink));}

